problems.tests:
test.public('the first call runs at once, the next ones wait for the window', () => {
  useFakeTimers();
  const spy = fn();
  const throttled = throttle(spy, 100);
  throttled(1);
  expect(spy.calls).toEqual([[1]]);
  throttled(2);
  advanceTimersByTime(30);
  throttled(3);
  expect(spy.calls).toEqual([[1]]);
});

test.public('the window ends with the last kept call', () => {
  useFakeTimers();
  const spy = fn();
  const throttled = throttle(spy, 100);
  throttled(1);
  advanceTimersByTime(30);
  throttled(2);
  advanceTimersByTime(30);
  throttled(3);
  advanceTimersByTime(40);
  expect(spy.calls).toEqual([[1], [3]]);
});

test('a trailing call opens the next window', () => {
  useFakeTimers();
  const spy = fn();
  const throttled = throttle(spy, 100);
  throttled(1);
  throttled(2);
  advanceTimersByTime(100); // runs 2, new window until 200
  throttled(3);
  advanceTimersByTime(50);
  expect(spy.calls).toEqual([[1], [2]]);
  advanceTimersByTime(50);
  expect(spy.calls).toEqual([[1], [2], [3]]);
});

test('goes idle after an empty window', () => {
  useFakeTimers();
  const spy = fn();
  const throttled = throttle(spy, 100);
  throttled(1);
  advanceTimersByTime(250);
  throttled(2);
  expect(spy.calls).toEqual([[1], [2]]);
});

test('steady calls run once per window, wait ms apart', () => {
  useFakeTimers();
  const start = Date.now();
  const times = [];
  const throttled = throttle(() => times.push(Date.now() - start), 100);
  for (let t = 0; t < 1000; t += 10) {
    throttled(t);
    advanceTimersByTime(10);
  }
  expect(times).toEqual([0, 100, 200, 300, 400, 500, 600, 700, 800, 900, 1000]);
});

test('keeps this', () => {
  useFakeTimers();
  const spy = fn();
  const a = { go: throttle(spy, 100) };
  a.go();
  a.go();
  advanceTimersByTime(100);
  expect(spy.contexts).toEqual([a, a]);
  expect(spy.contexts[1]).toBe(a);
});

test('cancel drops the kept call', () => {
  useFakeTimers();
  const spy = fn();
  const throttled = throttle(spy, 100);
  throttled(1);
  throttled(2);
  throttled.cancel();
  advanceTimersByTime(300);
  expect(spy.calls).toEqual([[1]]);
  throttled(3);
  expect(spy.calls).toEqual([[1], [3]]);
});

problems.solution:
function throttle(func, wait) {
  let timer = null;
  let kept = null; // { self, args } of the last call inside the window

  function openWindow() {
    timer = setTimeout(() => {
      if (!kept) {
        timer = null;
        return;
      }
      const call = kept;
      kept = null;
      func.apply(call.self, call.args);
      openWindow();
    }, wait);
  }
  function throttled(...args) {
    if (timer === null) {
      func.apply(this, args);
      openWindow();
    } else kept = { self: this, args };
  }
  throttled.cancel = () => {
    clearTimeout(timer);
    timer = null;
    kept = null;
  };
  return throttled;
}

statement.zh:
实现 `sleep(ms)`：返回一个 Promise，`ms` 毫秒后兑现（值为 `undefined`）。

```js
async function demo() {
  console.log('start');
  await sleep(500);
  console.log('500 ms later');
}
```

测试用假时钟，会检查 Promise 不早于 `ms` 毫秒兑现。

statement.en:
Implement `sleep(ms)`: return a Promise that fulfills (with `undefined`) after `ms` milliseconds.

```js
async function demo() {
  console.log('start');
  await sleep(500);
  console.log('500 ms later');
}
```

The tests use a fake clock and check that the Promise does not fulfill before `ms` ms.

problems.starter:
/**
 * @param {number} ms
 * @returns {Promise<void>}
 */
function sleep(ms) {
  // Your code here
}

problems.tests:
test.public('returns a promise', () => {
  useFakeTimers();
  expect(sleep(10)).toBeInstanceOf(Promise);
});

test.public('fulfills after ms, not before', async () => {
  useFakeTimers();
  let done = false;
  sleep(200).then(() => (done = true));
  await advanceTimersByTimeAsync(199);
  expect(done).toBe(false);
  await advanceTimersByTimeAsync(1);
  expect(done).toBe(true);
});

test('fulfills with undefined', async () => {
  useFakeTimers();
  const p = sleep(5);
  await advanceTimersByTimeAsync(5);
  await expect(p).resolves.toBeUndefined();
});

test('sleeps run side by side', async () => {
  useFakeTimers();
  const order = [];
  sleep(300).then(() => order.push(300));
  sleep(100).then(() => order.push(100));
  sleep(200).then(() => order.push(200));
  await advanceTimersByTimeAsync(300);
  expect(order).toEqual([100, 200, 300]);
});

test('sleep(0) still waits for a timer', async () => {
  useFakeTimers();
  let done = false;
  sleep(0).then(() => (done = true));
  await flushPromises();
  expect(done).toBe(false);
  await advanceTimersByTimeAsync(0);
  expect(done).toBe(true);
});

problems.solution:
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

problems.starter:
