  const tree = arrayToTree([
    { id: 'b', parentId: null },
    { id: 'a' },
    { id: 'c', parentId: 'a' },
  ]);
  expect(tree.map((n) => n.id)).toEqual(['b', 'a']);
  expect(tree[1].children.map((n) => n.id)).toEqual(['c']);
});

test('an orphan becomes a root', () => {
  const tree = arrayToTree([
    { id: 1, parentId: null },
    { id: 2, parentId: 99 },
  ]);
  expect(tree.map((n) => n.id)).toEqual([1, 2]);
});

test('id 0 is a real parent', () => {
  const tree = arrayToTree([
    { id: 0, parentId: null },
    { id: 1, parentId: 0 },
  ]);
  expect(tree).toHaveLength(1);
  expect(tree[0].children[0].id).toBe(1);
});

test('leaves the input alone', () => {
  const items = [
    { id: 1, parentId: null },
    { id: 2, parentId: 1 },
  ];
  const tree = arrayToTree(items);
  expect(items[0]).toEqual({ id: 1, parentId: null });
  expect(tree[0]).not.toBe(items[0]);
});

test('an empty list gives no roots', () => {
  expect(arrayToTree([])).toEqual([]);
});

test('a large list stays fast', () => {
  const items = [{ id: 0, parentId: null }];
  for (let i = 1; i < 20000; i++) items.push({ id: i, parentId: i - 1 });
  const started = Date.now();
  const tree = arrayToTree(items);
  expect(tree).toHaveLength(1);
  expect(Date.now() - started < 500).toBe(true);
});

problems.solution:
function arrayToTree(items) {
  const nodes = new Map();
  for (const item of items) nodes.set(item.id, { ...item, children: [] });
  const roots = [];
  for (const item of items) {
    const node = nodes.get(item.id);
    const parent = item.parentId === null || item.parentId === undefined ? undefined : nodes.get(item.parentId);
    if (parent) parent.children.push(node);
    else roots.push(node);
  }
  return roots;
}

statement.en:
Without the built-in `map`, implement `Array.prototype.myMap(callback, thisArg)` to behave like `Array.prototype.map`:

- call `callback(value, index, array)` for each element, with `this` set to `thisArg`, and collect the results into a **new array**;
- holes in the array (such as the second item of `[1, , 3]`) don't get a call and stay holes in the result;
- the range is fixed by the length at the start: elements pushed by the callback aren't visited;
- throw a `TypeError` if `callback` is not a function;
- it must work on array-like objects too: `Array.prototype.myMap.call({ length: 2, 0: 'a', 1: 'b' }, f)`.

```js
[1, 2, 3].myMap((x) => x * 2);   // [2, 4, 6]
[1, , 3].myMap((x) => x * 2);    // [2, , 6]
```

During the tests the built-in `Array.prototype.map` is replaced by a function that throws.

problems.starter:
/**
 * @param {(value: any, index: number, array: any[]) => any} callback
 * @param {any} [thisArg]
 * @returns {any[]}
 */
Array.prototype.myMap = function (callback, thisArg) {
  // Your code here
};

problems.tests:
/** Runs body with the built-in map switched off; restored before any expect. */
function own(body) {
  const saved = Array.prototype.map;
  Array.prototype.map = () => {
    throw new Error('Array.prototype.map is switched off: write your own');
  };
  try {
    return body();
  } finally {
    Array.prototype.map = saved;
  }
}

test.public('maps every element into a new array', () => {
  const input = [1, 2, 3];
  const out = own(() => input.myMap((x) => x * 2));
  expect(out).toEqual([2, 4, 6]);
  expect(out).not.toBe(input);
  expect(input).toEqual([1, 2, 3]);
});

test.public('the callback gets value, index and the array', () => {
  const input = ['a', 'b'];
  const spy = fn(() => 0);
  own(() => input.myMap(spy));
  expect(spy.calls).toEqual([
    ['a', 0, input],
    ['b', 1, input],
  ]);
  expect(spy.calls[0][2]).toBe(input);
});

test('thisArg becomes this', () => {
  const scale = { by: 10 };
  const out = own(() =>
    [1, 2].myMap(function (x) {
      return x * this.by;
    }, scale),
  );
  expect(out).toEqual([10, 20]);
});

test('holes are skipped and kept', () => {
  const spy = fn((x) => x * 2);
  const input = [1, 2, 3];
  delete input[1];
  const out = own(() => input.myMap(spy));
  expect(spy).toHaveBeenCalledTimes(2);
  expect(out.length).toBe(3);
  expect(1 in out).toBe(false);
  expect(out[2]).toBe(6);
});

test('elements added during the walk are not visited', () => {
  const input = [1, 2];
  const out = own(() =>
    input.myMap((x, i, arr) => {
      arr.push(x);
      return x;
    }),
  );
  expect(out).toEqual([1, 2]);
});

test('a non-function callback throws TypeError', () => {
  expect(() => own(() => [1].myMap('nope'))).toThrow(TypeError);
});

test('works on an array-like object', () => {
  const out = own(() => Array.prototype.myMap.call({ length: 2, 0: 'a', 1: 'b' }, (s) => s.toUpperCase()));
  expect(out).toEqual(['A', 'B']);
});

test('an undefined result is still an element', () => {
  const out = own(() => [1, 2].myMap(() => undefined));
  expect(out.length).toBe(2);
  expect(0 in out).toBe(true);
});

problems.solution:
Object.defineProperty(Array.prototype, 'myMap', {
  configurable: true,
  writable: true,
  value: function (callback, thisArg) {
    if (typeof callback !== 'function') throw new TypeError(callback + ' is not a function');
    const source = Object(this);
    const length = source.length >>> 0;
    const result = new Array(length);
    for (let i = 0; i < length; i++) {
      if (i in source) result[i] = callback.call(thisArg, source[i], i, source);
    }
    return result;
  },
});

